// `/config.json` is generated by the server per host: the game host answers `conveyor-game`,
// the operator host `conveyor-web` (ADR 0024). The client never invents a client id.

/**
 * @typedef {{issuer: string, clientId: string, devAuth: boolean}} WalkConfig
 */

/** @returns {Promise<WalkConfig>} */
export async function loadConfig() {
  const response = await fetch("/config.json", {
    cache: "no-store",
    credentials: "same-origin",
    headers: { accept: "application/json" },
  });
  if (!response.ok) {
    throw new Error(`config.json answered ${response.status}`);
  }
  const raw = await response.json();
  return {
    issuer: typeof raw.issuer === "string" ? raw.issuer : "",
    clientId: typeof raw.client_id === "string" ? raw.client_id : "",
    devAuth: raw.dev_auth === true,
  };
}

/**
 * @param {WalkConfig} config
 * @returns {{dev: boolean, oidc: boolean}}
 */
export function modes(config) {
  return {
    dev: config.devAuth,
    oidc: config.issuer.trim() !== "" && config.clientId.trim() !== "",
  };
}
